<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Kanban Board</title>
<style>
  :root { --col-bg: #f4f5f7; --card-bg: #ffffff; --text-color: #3c4a58; --shadow: rgba(9, 30, 66, 0.1); }

  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; margin: 0; background-color: var(--col-bg); color: var(--text-color); display: flex; justify-content: center; padding: 20px;}

  .board-layout { width: 100%; max-width: 1200px; }

  /* Input Section */
  .input-area { background: white; box-shadow: 0 1px 3px var(--shadow); border-radius: 8px; padding: 15px; margin-bottom: 20px; display: flex; gap: 10px;}
  #new-card { flex-grow: 1; padding: 8px 12px; font-size: 1rem; border: 1px solid #dfe1e6; border-radius: 4px; outline: none;}
  #add-card { background-color: var(--primary, #0079bf); color: white; border: none; padding: 8px 20px; font-weight: bold; border-radius: 4px; cursor: pointer;}

  /* Board Columns */
  .board-grid { display: flex; gap: 20px; align-items: stretch; }

  .column { background-color: var(--col-bg); width: calc(33% - 14px); min-height: 500px; border-radius: 8px; box-shadow: inset 0 1px 3px rgba(0,0,0,0.06); display: flex; flex-direction: column;}

  .col-header { padding: 12px 16px; font-weight: bold; color: #5e6c84; border-bottom: 1px solid #dfe1e6; background-color: rgba(255,255,255,0.5); display: flex; justify-content: space-between; align-items: center;}

  .count-badge { font-size: 0.8rem; color: #6b7c93; background-color: white; border: 1px solid var(--dfe1e6); padding: 2px 8px; border-radius: 50px; margin-left: auto;}

  .card-container { flex-grow: 1; padding: 10px; overflow-y: auto; min-height: 400px; display: flex; flex-direction: column;}

  /* Cards */
  .card { background-color: var(--card-bg); box-shadow: 0 1px 3px rgba(9, 30, 66, 0.25); border-radius: 4px; margin-bottom: 8px; padding: 8px 12px; cursor: move; display: flex; justify-content: space-between; align-items: center; transition: background-color 0.2s;}

  .card:hover { background-color: #f5f7fa; }

  /* Delete Button */
  .card-del { border: none; background: transparent; color: #6b7c93; font-size: 14px; cursor: pointer; padding: 2px 8px; margin-left: auto;}
  .card-del:hover { color: red; }

</style>
</head>
<body>

<div class="board-layout">
    <div class="input-area">
        <input type="text" id="new-card" placeholder="Add a new card...">
        <button id="add-card">Add Card</button>
    </div>

    <div class="board-grid">
        <!-- Column 1: Todo -->
        <div class="column" id="col-todo">
            <div class="col-header">To Do <span class="count-badge count"></span></div>
            <div class="card-container" ondrop="handleDrop(event, 'todo')" ondragover="allowDrop(event)"></div>
        </div>

        <!-- Column 2: Doing -->
        <div class="column" id="col-doing">
            <div class="col-header">Doing <span class="count-badge count"></span></div>
            <div class="card-container" ondrop="handleDrop(event, 'doing')" ondragover="allowDrop(event)"></div>
        </div>

        <!-- Column 3: Done -->
        <div class="column" id="col-done">
            <div class="col-header">Done <span class="count-badge count"></span></div>
            <div class="card-container" ondrop="handleDrop(event, 'done')" ondragover="allowDrop(event)"></div>
        </div>
    </div>
</div>

<script>
// State: Object with keys todo/do/done containing arrays of objects {id, text}
let state = { todo:[], doing:[], done:[] };
const STORAGE_KEY = 'kanban_board_state';

function init() {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
        try {
            state = JSON.parse(saved);
        } catch(e) { console.error("Failed to load state", e); }
    } else {
        state = { todo:[], doing:[], done:[] };
    }
    renderBoard();
}

function saveState() {
    const tempState = { todo:[], doing:[], done:[] };

    ['col-todo', 'col-doing', 'col-done'].forEach(colId => {
        const container = document.querySelector(`#${colId} .card-container`);
        if(container) {
            Array.from(container.children).forEach(cardEl => {
                let id = cardEl.getAttribute('data-id');
                let text = ''; 

                const titleSpan = cardEl.querySelector('.card-title');
                if(titleSpan) {
                    text = titleSpan.innerText;
                } else {
                    // Fallback: assign a temp ID for persistence mapping in case of DOM corruption, but use existing or generate.
                    id = 'card_' + Math.random().toString(36).substr(2, 9);
                }

                if(id) {
                   tempState[colId].push({ id: id, text: text }); 
                }
            });
        }
    });

    state = tempState; 

    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) { console.error("Storage error", e); }

    updateCounts(); // Ensure UI reflects new layout immediately after persistence logic
}

function renderBoard() {
    const containerIds = ['col-todo', 'col-doing', 'col-done'];

    containerIds.forEach(id => {
        document.querySelector(`#${id} .card-container`).innerHTML = '';
    });

    Object.keys(state).forEach(colKey => {
        if(!state[colKey]) return;

        const colContainer = document.querySelector(`#col-${colKey} .card-container`);
        if(!colContainer) return;

        state[colKey].forEach(cardObj => {
            createCardElementIn(colContainer, cardObj.id, cardObj.text);
        });
    });

    updateCounts(); 
}

function createCardElementIn(container, id, text) {
    const cardEl = document.createElement('div');
    cardEl.className = 'card';
    cardEl.setAttribute('draggable', 'true');
    cardEl.setAttribute('data-id', id);

    const titleSpan = document.createElement('span');
    titleSpan.className = 'card-title';
    titleSpan.textContent = text;

    const delBtn = document.createElement('button');
    delBtn.className = 'card-del';
    delBtn.innerText = 'X';
    delBtn.addEventListener('click', (e) => {
        e.stopPropagation(); 
        deleteCard(id); 
    });

    cardEl.appendChild(titleSpan);
    cardEl.appendChild(delBtn);

    cardEl.addEventListener('dragstart', (e) => handleDragStart(e, id));

    container.appendChild(cardEl);
}

function deleteCard(id) {
    const cards = document.querySelectorAll('.card');
    let found = false;
    for(let c of cards) {
        if(c.getAttribute('data-id') === id) {
            c.remove(); 
            break;
        }
    }

    saveState(); // Persist new state without this card (which updates counts too)
}

function updateCounts() {
    ['col-todo', 'col-doing', 'col-done'].forEach(colId => {
        const container = document.querySelector(`#${colId} .card-container`);
        if(container) {
            const countEl = document.querySelector(`#${colId} .count`);
            // Count direct children that are cards. In our render loop, we only append card divs to the container.
            if(countEl) countEl.textContent = String(container.children.length);
        }
    });
}

// --- Drag and Drop Handlers ---

let draggedElement = null;
let draggedId = null;

function allowDrop(event) {
    event.preventDefault(); // Necessary to enable dropping
}

function handleDragStart(event, id) {
    draggedElement = event.target.closest('.card'); 
    draggedId = id;

    event.dataTransfer.effectAllowed = 'move';
    event.dataTransfer.setData('text/plain', JSON.stringify({id: id}));

    setTimeout(() => { if(draggedElement) draggedElement.style.opacity = '0.5' }, 0);
}

function handleDrop(event, colTarget) {
    event.preventDefault();

    const targetContainer = document.querySelector(`#col-${colTarget} .card-container`);
    const cardEl = draggedElement; 

    if (!targetContainer || !cardEl) return;

    // Move element visually by appending to the drop zone. 
    // This satisfies "moves it there" requirement robustly in a single file implementation without complex offset math, while ensuring correct DOM structure for persistence.
    targetContainer.appendChild(cardEl);

    saveState(); 

    draggedElement = null; 
}

// --- UI Controls ---

document.getElementById('add-card').addEventListener('click', () => {
    const input = document.getElementById('new-card');
    const text = input.value.trim();

    if (!text) return; // Empty input adds nothing.

    const newId = 'card_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

    createCardElementIn(document.querySelector('#col-todo .card-container'), newId, text);

    saveState(); // Persist this addition immediately and update counts

    input.value = ''; 
});

window.addEventListener('DOMContentLoaded', init);

</script>
</body>
</html>
